// Marching-squares contours stitched into paths before corner-cut smoothing.
export function smoothPath(points,closed=true,passes=2){let out=points;for(let k=0;k<passes;k++){const next=[];if(!closed)next.push(out[0]);for(let i=0;i<(closed?out.length:out.length-1);i++){const a=out[i],b=out[(i+1)%out.length];next.push([a[0]*.75+b[0]*.25,a[1]*.75+b[1]*.25],[a[0]*.25+b[0]*.75,a[1]*.25+b[1]*.75])}if(!closed)next.push(out[out.length-1]);out=next}return out}
export function contours(value,w,h,level){const nodes=new Map(),edges=[];const node=p=>{const key=Math.round(p[0]*1000)+','+Math.round(p[1]*1000);if(!nodes.has(key))nodes.set(key,{p,edges:[]});return nodes.get(key)};
for(let y=1;y<h-2;y++)for(let x=1;x<w-2;x++){const id=x+y*w,a=value(id),b=value(id+1),c=value(id+w+1),d=value(id+w);if(![a,b,c,d].every(Number.isFinite))continue;const bits=(a>=level?1:0)|(b>=level?2:0)|(c>=level?4:0)|(d>=level?8:0);if(bits===0||bits===15)continue;const hits=[];if((a>=level)!==(b>=level))hits.push([x+(level-a)/(b-a),y]);if((b>=level)!==(c>=level))hits.push([x+1,y+(level-b)/(c-b)]);if((c>=level)!==(d>=level))hits.push([x+1-(level-c)/(d-c),y+1]);if((d>=level)!==(a>=level))hits.push([x,y+1-(level-d)/(a-d)]);for(let i=0;i+1<hits.length;i+=2){const edge={a:node(hits[i]),b:node(hits[i+1]),used:false};edge.a.edges.push(edge);edge.b.edges.push(edge);edges.push(edge)}}
const paths=[];for(const edge of edges){if(edge.used)continue;let start=edge.a.edges.length===1?edge.a:edge.b.edges.length===1?edge.b:edge.a,at=start,path=[at.p];while(true){const e=at.edges.find(e=>!e.used);if(!e)break;e.used=true;at=e.a===at?e.b:e.a;path.push(at.p);if(at===start)break}if(path.length<24)continue;const closed=at===start;if(closed)path.pop();paths.push({points:smoothPath(path,closed,2),closed})}return paths}
export function peopleBounds(mask,w,h){const cw=64,ch=48,grid=new Uint8Array(cw*ch),seen=new Uint8Array(grid.length),out=[];for(let y=0;y<ch;y++)for(let x=0;x<cw;x++)grid[x+y*cw]=mask[(Math.floor(x/cw*w)+Math.floor(y/ch*h)*w)*4]>150?1:0;for(let i=0;i<grid.length;i++){if(!grid[i]||seen[i])continue;const queue=[i];seen[i]=1;let minX=cw,maxX=0,minY=ch,maxY=0;for(let q=0;q<queue.length;q++){const at=queue[q],x=at%cw,y=Math.floor(at/cw);minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);for(const [nx,ny] of [[x-1,y],[x+1,y],[x,y-1],[x,y+1]]){const n=nx+ny*cw;if(nx>=0&&nx<cw&&ny>=0&&ny<ch&&grid[n]&&!seen[n]){seen[n]=1;queue.push(n)}}}if(queue.length>35)out.push({x:1-(minX+maxX+1)/(2*cw),y:(minY+maxY+1)/(2*ch),w:(maxX-minX+1)/cw,h:(maxY-minY+1)/ch})}return out.sort((a,b)=>a.x-b.x)}
